contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(stdin, str)",
      "description": "The input is a string."
    },
    {
      "id": "P2",
      "expression": "all(interval.startswith('{') and interval.endswith('}') for interval in stdin.strip('{}').split('},{'))",
      "description": "Each interval is enclosed in curly braces and separated by '},{'."
    },
    {
      "id": "P3",
      "expression": "all(len(interval.split(',')) == 2 for interval in stdin.strip('{}').split('},{'))",
      "description": "Each interval contains exactly two numbers separated by a comma."
    },
    {
      "id": "P4",
      "expression": "all(x.isdigit() and y.isdigit() for interval in stdin.strip('{}').split('},{') for x, y in [interval.split(',')])",
      "description": "Both numbers in each interval are non-negative integers."
    },
    {
      "id": "P5",
      "expression": "all(int(x) <= int(y) for interval in stdin.strip('{}').split('},{') for x, y in [interval.split(',')])",
      "description": "The first number in each interval is less than or equal to the second number."
    },
    {
      "id": "P6",
      "expression": "1 <= len(stdin.strip('{}').split('},{')) <= 100",
      "description": "The number of intervals is between 1 and 100."
    },
    {
      "id": "P7",
      "expression": "all(0 <= int(x) <= 1000 and 0 <= int(y) <= 1000 for interval in stdin.strip('{}').split('},{') for x, y in [interval.split(',')])",
      "description": "Each number in the intervals is between 0 and 1000."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "isinstance(stdout, str)",
      "description": "The output is a string."
    },
    {
      "id": "Q2",
      "expression": "all(interval.startswith('{') and interval.endswith('}') for interval in stdout.strip('{}').split('},{'))",
      "description": "Each interval in the output is enclosed in curly braces and separated by '},{'."
    },
    {
      "id": "Q3",
      "expression": "all(len(interval.split(',')) == 2 for interval in stdout.strip('{}').split('},{'))",
      "description": "Each interval in the output contains exactly two numbers separated by a comma."
    },
    {
      "id": "Q4",
      "expression": "all(x.isdigit() and y.isdigit() for interval in stdout.strip('{}').split('},{') for x, y in [interval.split(',')])",
      "description": "Both numbers in each interval in the output are non-negative integers."
    },
    {
      "id": "Q5",
      "expression": "all(int(x) <= int(y) for interval in stdout.strip('{}').split('},{') for x, y in [interval.split(',')])",
      "description": "The first number in each interval in the output is less than or equal to the second number."
    },
    {
      "id": "Q6",
      "expression": "all(intervals[i][0] <= intervals[i][1] for intervals in [stdout.strip('{}').split('},{')] for i in range(len(intervals)))",
      "description": "Each interval in the output is valid, with the start less than or equal to the end."
    },
    {
      "id": "Q7",
      "expression": "all(intervals[i][1] < intervals[i+1][0] for intervals in [stdout.strip('{}').split('},{')] for i in range(len(intervals)-1))",
      "description": "The intervals in the output are non-overlapping and sorted."
    },
    {
      "id": "Q8",
      "expression": "all(any(intervals[i][0] <= int(x) <= intervals[i][1] or int(x) <= intervals[i][0] <= int(y) for x, y in [interval.split(',')] for interval in stdin.strip('{}').split('},{')) for intervals in [stdout.strip('{}').split('},{')] for i in range(len(intervals)))",
      "description": "Each interval in the output is a merge of overlapping intervals from the input."
    }
  ],
